[method_builder] moveTableauRun try 1: 6p/5f  body='if (startIndex < 0 || startIndex >= tableau[from].size || to < 0 || to >= tableau.size) return false
val run = mutableListOf<Card>()
var i = startIndex
while (i < tableau[from].size && i > 0 && tableau[from][i].rank == tableau[from][i - 1].rank - 1 && tableau[from][i].red != tableau[from][i - 1].red) {
    run.add(tableau[from][i])
    i++
}
if (run.isEmpty()) return false
val toTop = tableau[to].lastOrNull()
if (toTop == null) {
    if (run.first().rank != 13) return false
} else {
    if (toTop.red == run.first().red || toTop.rank != run.first().rank - 1) return false
}
for (card in run) {
    tableau[from].removeLast()
}
tableau[to].addAll(run)
if (tableau[from].isNotEmpty()) tableau[from].last().faceUp = true
return true'

